ruleSearch.bookList:
.bookbox[0:9]
<js>
bookList = result;
h = java.getStringList(".bookname > a@href", bookList);

ht = h[1].includes("http") ? Array.from(h) : Array.from(h, x => `${source.key}${x}`);

d = java.ajaxAll(ht).map(x => x.body());

$=(b,c)=>java.getString(b,c);

Array.from(bookList,(a,i)=>{
	list={
		name:$(".bookname > a@text",a),
		author:$(".author:nth-child(2)@text##作者：",a),
		kind:$("li:nth-child(2) > a@text",d[i]),
		words:$(".blue:nth-child(2)@text",d[i]),
		lastc:$("a:nth-child(2)@text",a),
		intro:$(".update@text##简介：",a),
		cover:$(".bookcover > .thumbnail@src",d[i]),
		link:$(".bookname > a@href",a)
		};
		return list
	});
</js>

ruleToc.chapterUrl:
href
<js>
rex = result.match(/(\d+)\/(\d+)\.html/);
bid = rex[1];
cid = rex[2];
body = `articleid=${bid}&chapterid=${cid}&pid=1`;
u = "/api/reader_js.php";
`${u},{
  "body": "${body}",
  "method": "POST"
}`
</js>
